'use strict';
const energyNumber=n=>Number(n).toLocaleString('zh-TW',{maximumFractionDigits:2});
const energyFields={gridMin:{id:'grid-min',label:'供電下限：電量用到多少就停？',short:'平常供電下限'},gridMax:{id:'grid-max',label:'充電上限：電量充到多少就停？',short:'平常充電上限'},islandMin:{id:'island-min',label:'供電下限：電量用到多少就停？',short:'停電供電下限'},islandMax:{id:'island-max',label:'充電上限：電量充到多少就停？',short:'停電充電上限'},contractKw:{id:'contract-capacity',label:'契約容量（kW）',short:'契約容量'},triggerPct:{id:'demand-percent',label:'需量達到契約容量的多少百分比時，請電池供電？',short:'啟動百分比'}};
let energyDraft=null,energyErrorsShown=false,energyTrial={mode:'grid',soc:72,demand:950};
function clearEnergyDraft(){energyDraft=null;energyErrorsShown=false;}
function energyValues(){return energyDraft||state.energySettings;}
function energyDirty(){return EnergySettings.keys.some(k=>String(energyValues()[k])!==String(state.energySettings[k]));}
function energyField(key,help){const f=energyFields[key],unit=key==='contractKw'?'kW':'%',min=key==='contractKw'||key==='triggerPct'?1:10,max=key==='contractKw'?'':`max="${key==='triggerPct'?100:95}"`;return `<div class="field"><label for="${f.id}">${f.label}</label><div class="energy-input-unit"><input id="${f.id}" name="${key}" type="number" min="${min}" ${max} step="1" required value="${esc(energyValues()[key])}" ${blocked()?'disabled':''} aria-describedby="${f.id}-help ${f.id}-error"><span aria-hidden="true">${unit}</span></div><p class="help-text" id="${f.id}-help">${help}</p><p class="error" id="${f.id}-error"></p></div>`;}
function energyRange(c,label,minKey,maxKey){return `<div class="energy-range"><div class="energy-range-heading"><strong>${label}</strong><span>${c[minKey]}% ～ ${c[maxKey]}%</span></div><div class="energy-range-track" aria-hidden="true"><span style="left:${c[minKey]}%;width:${c[maxKey]-c[minKey]}%"></span></div><div class="energy-range-scale"><span>0% 沒有電</span><span>100% 充滿</span></div></div>`;}
function energyPreview(){const r=EnergySettings.validate(energyValues());return !r.valid?'<p class="note warn">請先修正設定數字，才能顯示完整範圍。</p>':`${energyRange(r.values,'平常有台電', 'gridMin','gridMax')}${energyRange(r.values,'停電自行供電','islandMin','islandMax')}<p class="help-text">停電範圍較寬：可以多用一些電；有太陽能等電力可充時，也能多存一些。切換模式不會立刻增加電池現有電量。</p>`;}
function energyFormula(){const r=EnergySettings.validate(energyValues());return r.valid?`<span>${energyNumber(r.values.contractKw)} kW × ${r.values.triggerPct}%</span><strong>＝ ${energyNumber(EnergySettings.threshold(r.values))} kW</strong><p>最新需量達到或超過這個數字，就符合啟動門檻。</p>`:'<p>請填寫完整、有效的設定，才能計算啟動門檻。</p>';}
function energyTrialResult(){const r=EnergySettings.validate(energyValues());if(!r.valid)return '<p class="note warn">請先修正上方設定，再查看試算。</p>';try{const v=EnergySettings.evaluate(r.values,{...energyTrial,policy:state.policy});return `<div class="energy-decision ${v.code==='reserve'?'warn':''}"><h3>${v.title}</h3><p>${v.detail}</p></div><div class="energy-trial-facts"><p><strong>本次電量範圍：</strong>${v.min}% ～ ${v.max}%</p><p><strong>充電判斷：</strong>${v.charging}</p><p><strong>需量門檻：</strong>${energyTrial.mode==='island'?'停電模式不使用契約需量門檻':energyNumber(v.threshold)+' kW'}</p></div><p class="help-text">依${energyDirty()?'尚未儲存的試填值':'目前儲存的示範設定'}試算。這不是設備已啟動的回報，也不保證供電時數。</p>`;}catch{return '<p class="note warn">試算電量請填 0%～100%，測試需量請填大於或等於 0 的數字。</p>';}}
function renderEnergySettings(){return `<section class="card section-space"><h2>先看懂：SoC 就是電池還剩多少電</h2><p class="section-space">像手機的電量百分比，<strong>SoC 50% 就是大約還有一半電</strong>。它不是剩餘使用時間；能撐多久，還要看設備用了多少電。</p><div class="energy-explain"><p><strong>供電下限</strong><br>電量用到這裡，就停止由電池繼續供電，避免把預留的電也用完。</p><p><strong>充電上限</strong><br>電量充到這裡，就停止繼續充電，避免一直把電池充得太滿。</p></div></section><form id="settings-form" class="energy-settings-form section-space" novalidate><div id="settings-error" class="error energy-error-summary" role="alert" tabindex="-1"></div><fieldset class="card energy-fieldset"><legend>1. 平常有台電供電時（併聯運轉）</legend><p>平常把電量維持在較窄的範圍，讓電池保留餘裕，也留一些電應付停電。</p><div class="energy-fields section-space">${energyField('gridMin','到達這個下限，就停止用電池協助平常用電。')}${energyField('gridMax','到達這個上限，就停止繼續充電。')}</div></fieldset><fieldset class="card energy-fieldset"><legend>2. 台電停電、自行供電時（孤島運轉）</legend><p>防災時希望重要設備多撐一段時間，因此<strong>下限設得更低、上限設得更高</strong>，讓可用的電量範圍比平常寬。</p><div class="energy-fields section-space">${energyField('islandMin','要比平常下限低。到達後停止由電池供電，交由現場安排其他電源。')}${energyField('islandMax','要比平常上限高。有太陽能等電力可充時，可以多存一些電。')}</div><div id="energy-range-preview" class="section-space">${energyPreview()}</div><p class="help-text section-space">本示範可填 10%～95%，不是設備通用安全範圍；正式上下限須經現場確認。提高上限不會立刻增加電量，仍要有電可充，也需要充電時間。</p></fieldset><fieldset class="card energy-fieldset"><legend>3. 用電到多少，請電池幫忙？</legend><p><strong>契約容量</strong>是學校與台電約定的用電容量，請依電費單或核定資料填寫。這裡的設定只供系統判斷，不會替您變更台電契約。</p><p><strong>即時需量</strong>可以想成「學校這段時間向台電要多少電力」，單位是 kW。這裡看總電表最新回報的需量；台電計費採 15 分鐘平均，仍以台電電表為準。</p><div class="energy-fields section-space">${energyField('contractKw','填寫大於 0 的整數，單位 kW；這不是累積用了幾度電。')}${energyField('triggerPct','可填 1%～100%。百分比設得越低，電池就越早開始幫忙。')}</div><div id="energy-demand-formula" class="energy-formula section-space" aria-live="polite">${energyFormula()}</div><p class="help-text">需量達到門檻，且電池高於併聯供電下限時，才可啟動供電；實際仍受設備狀況與供電策略限制。選擇「優先保留備用電」時，平常暫停需量支援。</p></fieldset><div class="card"><p class="note">以下為示範設定，並非校方已核定值。儲存前會列出新設定，請確認後再送出。</p><p id="energy-dirty" class="help-text section-space" role="status">${energyDirty()?'數字已更改，尚未儲存。':'目前顯示已儲存的示範設定。'}</p><div class="actions section-space"><button class="primary" type="submit" ${blocked()?'disabled':''}>檢查並儲存設定</button><button type="button" data-action="discard-energy" ${!permission()||!energyDirty()?'disabled':''}>放棄尚未儲存的變更</button></div></div></form>`;}
function renderEnergyTrial(){return `<details class="card section-space energy-trial"><summary>看看這組設定何時會啟動電池</summary><p class="section-space">下面只改變試算數字，不會更改設定、既有示範情境或現場設備。</p><div class="energy-fields section-space"><div class="field"><label for="trial-mode">想看哪種供電情況？</label><select id="trial-mode"><option value="grid" ${energyTrial.mode==='grid'?'selected':''}>平常有台電（併聯）</option><option value="island" ${energyTrial.mode==='island'?'selected':''}>台電停電（孤島）</option></select></div><div class="field"><label for="trial-soc">測試電池剩餘電量（%）</label><input id="trial-soc" type="number" min="0" max="100" value="${energyTrial.soc}"></div><div class="field" id="trial-demand-field" ${energyTrial.mode==='island'?'hidden':''}><label for="trial-demand">測試需量（kW，電池介入前）</label><input id="trial-demand" type="number" min="0" value="${energyTrial.demand}"><p class="help-text">獨立試算數值，不是總覽的台電取電量。</p></div></div><div id="energy-trial-result" class="section-space" aria-live="polite">${energyTrialResult()}</div></details>`;}
function updateEnergyFeedback(showErrors=false){
  const form=$('#settings-form');if(!form)return;energyErrorsShown=energyErrorsShown||showErrors;
  const r=EnergySettings.validate(energyValues());
  for(const [key,f] of Object.entries(energyFields)){const message=energyErrorsShown?r.errors[key]||'':'';$('#'+f.id).setAttribute('aria-invalid',String(!!message));$('#'+f.id+'-error').textContent=message;}
  $('#settings-error').innerHTML=energyErrorsShown&&!r.valid?`<strong>請先修正以下設定：</strong><ul>${Object.entries(r.errors).map(([key,message])=>`<li><a href="#${energyFields[key].id}">${energyFields[key].short}：${message}</a></li>`).join('')}</ul>`:'';
  $('#energy-range-preview').innerHTML=energyPreview();$('#energy-demand-formula').innerHTML=energyFormula();$('#energy-dirty').textContent=energyDirty()?'數字已更改，尚未儲存。':'目前顯示已儲存的示範設定。';$('[data-action=discard-energy]').disabled=!permission()||!energyDirty();$('#energy-trial-result').innerHTML=energyTrialResult();
}
function saveEnergySettings(values){
  if(!authorize()||!connected())return;energyDraft={...values};const result=EnergySettings.validate(values);updateEnergyFeedback(true);
  if(!result.valid){$('#settings-error').focus();return;}
  const c=result.values;confirmOperation('確認這組電池與需量設定？',`<p><strong>平常有台電：</strong>供電下限 ${c.gridMin}%，充電上限 ${c.gridMax}%。</p><p><strong>停電自行供電：</strong>供電下限 ${c.islandMin}%，充電上限 ${c.islandMax}%。</p><p><strong>契約容量：</strong>${energyNumber(c.contractKw)} kW。</p><p><strong>啟動條件：</strong>即時需量達 ${c.triggerPct}%（${energyNumber(EnergySettings.threshold(c))} kW）時，請電池協助供電。</p><p>到達電量下限就停止電池供電；到達上限就停止充電。這次只儲存示範設定，不代表設備已啟動。</p>`,()=>{state.energySettings={...c};clearEnergyDraft();log(`設定更新：併聯 SoC ${c.gridMin}%～${c.gridMax}%，孤島 SoC ${c.islandMin}%～${c.islandMax}%；契約容量 ${c.contractKw} kW，需量達 ${c.triggerPct}%（${EnergySettings.threshold(c)} kW）啟動儲能。`);return '兩組電池上下限、契約容量與啟動門檻已儲存為示範設定。';});
}
document.addEventListener('input',e=>{const key=Object.keys(energyFields).find(k=>energyFields[k].id===e.target.id);if(key){if(!permission()){e.target.value=energyValues()[key];return;}energyDraft={...energyValues(),[key]:e.target.value};updateEnergyFeedback();}if(['trial-soc','trial-demand'].includes(e.target.id)){energyTrial[e.target.id==='trial-soc'?'soc':'demand']=e.target.value.trim()===''?NaN:Number(e.target.value);$('#energy-trial-result').innerHTML=energyTrialResult();}});
document.addEventListener('focusout',e=>{if(Object.values(energyFields).some(f=>f.id===e.target.id)&&!e.relatedTarget?.closest('#settings-form button'))updateEnergyFeedback(true);});
document.addEventListener('change',e=>{if(e.target.id==='trial-mode'){energyTrial.mode=e.target.value;$('#trial-demand-field').hidden=energyTrial.mode==='island';$('#energy-trial-result').innerHTML=energyTrialResult();}});
document.addEventListener('click',e=>{const link=e.target.closest('#settings-error a');if(link){e.preventDefault();$(link.getAttribute('href'))?.focus();}});
